// === Tab: mySketch ===
// Translated to p5.js fork: oggy  https://openprocessing.org/sketch/555063
// 潮汐色彩版本 - 浅色调优化

const gridSize = 55;
const dotSpacing = 8;
const influenceRadius = 50;
const maxDistortion = 15;

let dots = [];
let tideColors = []; // 存储潮汐渐变颜色

function setup() {
  createCanvas(600, 600);

  // 初始化浅色调潮汐颜色渐变 - 从浅蓝到青绿的渐变
  tideColors = [
    color(30, 60, 100),     // 浅海蓝
    color(40, 80, 120),    // 中浅蓝
    color(50, 100, 140),   // 浅海蓝
    color(60, 120, 160),   // 海面青
    color(80, 140, 180),   // 浪尖青
    color(100, 160, 200),  // 泡沫浅蓝
    color(120, 180, 220),  // 高光浅蓝
    color(140, 200, 240)   // 潮汐最亮
  ];

  // 初始化网格点
  const offset = (width - gridSize * dotSpacing) / 2;

  for (let i = 0; i < gridSize; i++) {
    dots[i] = [];
    for (let j = 0; j < gridSize; j++) {
      dots[i][j] = new Dot(i * dotSpacing + offset, j * dotSpacing + offset);
    }
  }
}

function draw() {
  // 绘制浅色调潮汐渐变背景
  drawLightTideBackground();

  const mousePosition = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  // 更新并绘制所有点
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      dots[i][j].update(mousePosition);
    }
  }
}

function drawLightTideBackground() {
  // 创建浅色调径向渐变背景
  for (let r = max(width, height); r > 0; r -= 2) {
    // 根据半径计算颜色 - 中心最亮，边缘稍深
    let inter = map(r, 0, max(width, height) * 0.8, 0, 1);
    inter = constrain(inter, 0, 1);

    // 浅蓝到中蓝的渐变
    let c1 = color(40, 80, 120);    // 中心浅蓝
    let c2 = color(20, 50, 90);     // 边缘稍深的蓝
    let bgColor = lerpColor(c1, c2, inter);

    // 添加轻微的不规则性模拟水面波动
    let waveOffset = sin(frameCount * 0.01 + r * 0.01) * 8;
    bgColor.levels[0] = constrain(bgColor.levels[0] + waveOffset, 20, 240);
    bgColor.levels[1] = constrain(bgColor.levels[1] + waveOffset * 0.8, 40, 240);
    bgColor.levels[2] = constrain(bgColor.levels[2] + waveOffset * 0.9, 60, 250);

    fill(bgColor);
    noStroke();
    ellipse(width/2, height/2, r, r);
  }

  // 添加一些浅色水面高光效果
  push();
  noStroke();
  for (let i = 0; i < 5; i++) {
    let alpha = 20 + sin(frameCount * 0.02 + i) * 10;
    let size = 100 + i * 50;
    let x = width/2 + cos(frameCount * 0.01 + i) * 50;
    let y = height/2 + sin(frameCount * 0.015 + i) * 30;

    fill(180, 220, 255, alpha);
    ellipse(x, y, size, size);
  }
  pop();
}

class Dot {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.originalPosition = this.position.copy();
    this.velocity = createVector(0, 0);
    this.baseHue = random(190, 210); // 更浅的蓝色调
    this.hueVariation = random(15, 30); // 减少色调变化范围
  }

  update(mousePos) {
    // 计算到鼠标的向量
    let vecToMouse = this.originalPosition.copy();
    vecToMouse.sub(mousePos);
    const distanceToMouse = vecToMouse.mag();

    // 映射距离到相位值用于正弦扭曲
    const phase = map(distanceToMouse, 0, influenceRadius, 0, PI);

    // 归一化并缩放扭曲向量
    vecToMouse.normalize();
    vecToMouse.mult(maxDistortion * sin(phase));

    // 基于距离计算线条粗细
    let strokeWidth;
    if (distanceToMouse < influenceRadius) {
      strokeWidth = 1 + 10 * abs(cos(phase / 2));
    } else {
      strokeWidth = map(min(distanceToMouse, width), 0, width, 5, 0.1);
    }

    // 计算目标位置（带扭曲）
    const targetPosition = createVector(
      this.originalPosition.x + vecToMouse.x,
      this.originalPosition.y + vecToMouse.y
    );

    // 计算吸引力
    let attractionVector = this.position.copy();
    attractionVector.sub(targetPosition);
    const attractionStrength = map(
      mousePos.dist(this.position),
      0,
      2 * width,
      0.1,
      0.01
    );
    attractionVector.mult(-attractionStrength);

    this.velocity.add(attractionVector);
    this.velocity.mult(0.87);  // 摩擦/阻尼

    this.position.add(this.velocity);

    // 计算浅色调潮汐颜色

    // 1. 基础深度层：根据Y坐标（深度）变化，但范围更浅
    let depthFactor = map(this.originalPosition.y, 0, height, 0, 1);
    let depthColorIndex = floor(depthFactor * (tideColors.length - 1));
    depthColorIndex = constrain(depthColorIndex, 0, tideColors.length - 2);

    let baseColor = lerpColor(
      tideColors[depthColorIndex],
      tideColors[depthColorIndex + 1],
      depthFactor * (tideColors.length - 1) - depthColorIndex
    );

    // 2. 潮汐波动层：更明显的浅色调波动
    let timeWave = sin(frameCount * 0.05 + this.originalPosition.x * 0.01 + this.originalPosition.y * 0.01) * 0.5;

    // 3. 鼠标交互层：更亮的鼠标光晕
    let mouseGlow = 0;
    if (distanceToMouse < influenceRadius * 2) {
      mouseGlow = map(distanceToMouse, 0, influenceRadius * 2, 1.2, 0);
      mouseGlow *= sin(phase) * 0.6;
    }

    // 4. 动态层：基于速度的颜色变化
    let speed = this.velocity.mag();
    let speedEffect = map(speed, 0, 2, 0, 0.5);

    // 组合所有颜色效果，整体提亮
    let r = red(baseColor) + timeWave * 25 + mouseGlow * 60 + speedEffect * 40;
    let g = green(baseColor) + timeWave * 30 + mouseGlow * 80 + speedEffect * 60;
    let b = blue(baseColor) + timeWave * 35 + mouseGlow * 100 + speedEffect * 80;

    // 约束颜色值，保持浅色调范围
    r = constrain(r, 40, 240);
    g = constrain(g, 60, 240);
    b = constrain(b, 100, 255);

    // 应用更浅的颜色
    let dotColor = color(r, g, b);

    // 设置透明度 - 整体更透明
    var alpha = map(this.position.dist(createVector(width/2, height/2)), 0, width/2, 220, 100);
    dotColor.setAlpha(alpha);

    // 绘制主点
    stroke(dotColor);
    strokeWeight(strokeWidth);
    point(this.position.x, this.position.y);

    // 鼠标附近添加更亮的高光效果
    if (distanceToMouse < influenceRadius) {
      let highlightAlpha = map(distanceToMouse, 0, influenceRadius, 120, 0);
      let highlightColor = color(200, 240, 255, highlightAlpha);
      stroke(highlightColor);
      strokeWeight(strokeWidth * 1.8);
      point(this.position.x, this.position.y);
    }

    // 添加微弱的发光效果
    if (distanceToMouse < influenceRadius * 1.5) {
      let glowAlpha = map(distanceToMouse, 0, influenceRadius * 1.5, 40, 0);
      let glowColor = color(180, 220, 255, glowAlpha);
      stroke(glowColor);
      strokeWeight(strokeWidth * 0.7);
      point(this.position.x, this.position.y);
    }
  }
}

